hooks.command:
node -e '
let d="";process.stdin.on("data",c=>d+=c);process.stdin.on("end",()=>{
  let cmd="";
  try { cmd = JSON.parse(d).tool_input.command || ""; } catch(e) {}
  const actionRe = /(git\s+mv|(^|[;&|\s])mv\s|rm\s+-[a-zA-Z]*r)/i;
  const folderRe = /(expert-products|cat-images|Bahar-Products|marhaba-products|Banners)/i;
  if (actionRe.test(cmd) && folderRe.test(cmd)) {
    const msg = "Before moving, renaming, or deleting this image folder: query Supabase first to check whether expert_photos.img_url or expert_products.img_url store an ABSOLUTE URL pointing at it (e.g. https://mukarramkebra.github.io/Hardware-Website/FOLDER/...) using an ilike wildcard match on the folder name against both expert_photos.img_url and expert_products.img_url. Renaming without checking has broken live product images twice already in this project. See CLAUDE.md, Hard-won gotchas section, for the full writeup.";
    process.stdout.write(JSON.stringify({hookSpecificOutput:{hookEventName:"PreToolUse",additionalContext:msg}}));
  }
});
'
